import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Hearth OS · MCP 与任务委派设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-MCP与任务委派设计说明.md","filePath":"architecture/Hearth-MCP与任务委派设计说明.md","lastUpdated":null}'),o={name:"architecture/Hearth-MCP与任务委派设计说明.md"};function h(s,t,l,n,i,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="hearth-os-·-mcp-与任务委派设计说明" tabindex="-1">Hearth OS · MCP 与任务委派设计说明 <a class="header-anchor" href="#hearth-os-·-mcp-与任务委派设计说明" aria-label="Permalink to &quot;Hearth OS · MCP 与任务委派设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>apps/server/src</code> 下 MCP、子代理、委派与交接相关文件），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>交接包里有什么、提示词超预算如何降级</td><td><a href="./hearth-os-上下文管理设计.html">hearth-os-上下文管理设计</a></td><td>只讲交接包的<strong>校验与写入断言</strong>，不重讲内容编排</td></tr><tr><td>MCP 工具会触发审批</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>不重讲审批流程</td></tr><tr><td>AgentTool 契约、十六个内置工具</td><td><a href="./Hearth-Agent运行时设计说明.html">Hearth-Agent运行时设计说明</a></td><td>只讲追加的工具如何适配该契约</td></tr><tr><td>工作树如何创建与清理</td><td><a href="./Hearth-工作区隔离与产物设计说明.html">Hearth-工作区隔离与产物设计说明</a></td><td>只讲子代理如何使用它</td></tr></tbody></table><p>本文只讲：<strong>外部工具怎么接进 Agent、Agent 怎么分身、任务怎么委派、以及跨执行器交接时如何防止「旧代次乱写」</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>这是三条彼此独立的扩展通道：</p><ol><li><strong>MCP</strong>：把外部工具服务器包装成 Agent 能调用的工具；</li><li><strong>子代理</strong>：在一次 Agent 运行内派生只读或隔离写入的分身；</li><li><strong>委派与交接</strong>：跨任务、跨执行器地转移工作，并用代次与权限断言保证写入安全。</li></ol><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为三者是同一套「多 Agent」机制</td><td>层次完全不同：MCP 是工具、子代理是运行内分身、委派是跨任务 job</td></tr><tr><td>以为子代理能无限递归</td><td>最多 2 个、只有一层，子代理的工具集里没有「再派一个」</td></tr><tr><td>以为交接包拿到就能写</td><td>每次写入前要过代次、执行器身份、权限三道断言，越界直接拒绝</td></tr></tbody></table><hr><h2 id="_2-mcp-从外部服务器到统一工具" tabindex="-1">2. MCP：从外部服务器到统一工具 <a class="header-anchor" href="#_2-mcp-从外部服务器到统一工具" aria-label="Permalink to &quot;2. MCP：从外部服务器到统一工具&quot;">​</a></h2><p>传输方式只有一种：标准输入输出的子进程。配置项是名称、命令、参数、环境变量、是否启用；环境变量里的密钥走加密箱。探测时启动客户端、连接、列出工具，成功后缓存工具描述与参数结构。服务标识是固定前缀加 8 位随机串。</p><p>一道完整的上限体系，防止外部服务器把系统拖垮：</p><table tabindex="0"><thead><tr><th>项</th><th>上限</th></tr></thead><tbody><tr><td>单个服务器的工具数</td><td>100（超出直接拒绝）</td></tr><tr><td>工具描述 / 工具名</td><td>2 千字符 / 128 字符，名称需符合字符规则</td></tr><tr><td>参数结构</td><td>6.4 万字符</td></tr><tr><td>探测错误信息</td><td>1 千字符，且先脱敏再截断</td></tr><tr><td>单次调用结果</td><td>10 万字符，超出截断并附原始长度</td></tr><tr><td>调用超时</td><td>默认 12 秒，可配置 1–60 秒</td></tr></tbody></table><p>超时与调用失败分别映射成网关式错误码（504 / 502）。探测错误<strong>先脱敏再截断</strong>，避免把配置里的密钥回显到错误信息里。</p><hr><h2 id="_3-工具命名与冲突检测" tabindex="-1">3. 工具命名与冲突检测 <a class="header-anchor" href="#_3-工具命名与冲突检测" aria-label="Permalink to &quot;3. 工具命名与冲突检测&quot;">​</a></h2><p>包装后的工具名是「前缀 + 服务器标识 + 工具名」的三段式，用<strong>双下划线</strong>分隔；而服务器标识本身是<strong>单下划线</strong>加随机串。解析函数靠双下划线前缀反解，这两种写法很容易看混。</p><p>登记前会先建立一份黑名单：十六个内置工具，加上网页搜索、加载技能、读技能资源、委派任务四个<strong>预留名</strong>。任何 MCP 工具撞上这些名字都会被拒绝。这样做的好处是外部服务器永远无法覆盖系统自带能力，即使它故意提供一个同名工具。</p><hr><h2 id="_4-子代理-运行内的两个分身" tabindex="-1">4. 子代理：运行内的两个分身 <a class="header-anchor" href="#_4-子代理-运行内的两个分身" aria-label="Permalink to &quot;4. 子代理：运行内的两个分身&quot;">​</a></h2><p>通过「委派任务」工具派生，最多 2 个、单层。两种模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>权限与工作区</th></tr></thead><tbody><tr><td>只读</td><td>工具集收敛为「结束任务」加上父权限里属于只读白名单的那些工具</td></tr><tr><td>隔离写入</td><td>从父任务当前提交开一个独立工作树，完成后单独提交；拥有独立的根目录与输出目录</td></tr></tbody></table><p>子代理有完全独立的预算：40 轮、400 次工具调用、20 万 token、10 分钟。因此一个失控的分身不会吃掉父任务的预算。</p><p>注意这里有<strong>两套不同的白名单</strong>：给子代理用的「只读工具集」，和给跨进程委派 job 用的「安全工具集」（后者只有 7 个工具）。名字相近，用途不同。</p><hr><h2 id="_5-委派-job-带租约的状态机" tabindex="-1">5. 委派 job：带租约的状态机 <a class="header-anchor" href="#_5-委派-job-带租约的状态机" aria-label="Permalink to &quot;5. 委派 job：带租约的状态机&quot;">​</a></h2><p>委派是跨任务的工作单元，状态共 8 种：排队、已租、运行中、待验证、成功、失败、取消、孤儿。活跃状态包含「待验证」，但<strong>租约接口又明确排除它</strong>——所以「活跃」不等于「可被领取」。</p><table tabindex="0"><thead><tr><th>项</th><th>规则</th></tr></thead><tbody><tr><td>租约与心跳</td><td>默认 30 秒，可配置</td></tr><tr><td>完成流程</td><td>完成后进入「待验证」，验证通过才是「成功」，否则「失败」</td></tr><tr><td>安全工具集</td><td>仅 7 个工具，且必须同时出现在父权限与该白名单内</td></tr><tr><td>预算归一化</td><td>只保留 token、墙钟时长、步数三项，且必须为正数</td></tr><tr><td>孤儿回收</td><td>父任务已完成 / 失败 / 取消或不存在时，job 被标记为孤儿</td></tr><tr><td>取消连锁</td><td>取消 job 会连带取消未终态的子任务；已终态子任务已被栅栏保护</td></tr></tbody></table><p>工作区默认落在数据目录的 delegations 子目录。</p><hr><h2 id="_6-交接包-代次、校验与写入断言" tabindex="-1">6. 交接包：代次、校验与写入断言 <a class="header-anchor" href="#_6-交接包-代次、校验与写入断言" aria-label="Permalink to &quot;6. 交接包：代次、校验与写入断言&quot;">​</a></h2><p>准备交接包时会做四件事：把代次设为「历史最大代次 + 1」、记录来源游标、打上统一的脱敏策略标记并列出被脱敏字段、生成一组默认验证项。验证时检查代次为正、游标合法、目标与下一步动作存在、验收项与权限齐全、产物哈希一致。</p><p><strong>三类写入断言</strong>是这套设计最硬的部分：</p><table tabindex="0"><thead><tr><th>断言</th><th>拒绝条件</th></tr></thead><tbody><tr><td>代次新鲜度</td><td>当前包代次小于最新代次，说明是过期包，拒绝</td></tr><tr><td>执行器身份</td><td>同代次里目标执行器不符、且该交接未结束，拒绝；但已结束的交接放行</td></tr><tr><td>权限不扩大</td><td>逐项比对可读根、可写根、网络主机、工具名单；父任务没声明的权限一律拒绝，交接包不能自行扩权</td></tr></tbody></table><p>冲突检测还有一层去重：同一实体同一属性同一值的冲突会用固定键去重，避免反复生成待办。</p><hr><h2 id="_7-只读代码才会发现的事实" tabindex="-1">7. 只读代码才会发现的事实 <a class="header-anchor" href="#_7-只读代码才会发现的事实" aria-label="Permalink to &quot;7. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>工具名是双下划线三段式，服务器标识是单下划线，两者极易混淆。</li><li>工具名黑名单里有 4 个<strong>预留但未必已实现</strong>的名字，是为未来扩展留的坑位。</li><li>「活跃状态」包含待验证，但待验证不可被租；完成 ≠ 成功，要过验证。</li><li>交接的执行器不符断言有一个例外：该交接已结束时放行。</li><li>权限断言是逐项比对，交接包不能自己给自己加权限。</li><li>子代理白名单与委派 job 白名单是两套独立集合。</li></ol><hr><h2 id="_8-与其它模块的分界" tabindex="-1">8. 与其它模块的分界 <a class="header-anchor" href="#_8-与其它模块的分界" aria-label="Permalink to &quot;8. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>MCP 服务器配置、AgentTool 契约、父任务权限与工作树、任务状态、目标执行器、上下文水位</td></tr><tr><td>输出</td><td>追加的工具、子代理事件与独立提交、委派 job 与事件、交接包及校验结果</td></tr><tr><td>不讲</td><td>交接包内容编排与提示词降级（上下文）、审批判定（判定审批）、工作树命令细节（工作区）、运行时循环（Agent 运行时）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>MCP 服务器配置、探测、调用与上限</td><td><code>apps/server/src/mcp-servers.ts</code></td></tr><tr><td>工具包装、命名与黑名单</td><td><code>apps/server/src/mcp-tools.ts</code></td></tr><tr><td>子代理与独立预算</td><td><code>apps/server/src/subagents.ts</code></td></tr><tr><td>委派 job 状态机与孤儿回收</td><td><code>apps/server/src/delegation.ts</code></td></tr><tr><td>交接包准备、验证与写入断言</td><td><code>apps/server/src/handoff.ts</code></td></tr><tr><td>脱敏原语</td><td><code>apps/server/src/context.ts</code></td></tr><tr><td>任务图与工作树</td><td><code>apps/server/src/task-graph.ts</code>、<code>worktrees.ts</code></td></tr></tbody></table>',48)])])}const _=d(o,[["render",h]]);export{p as __pageData,_ as default};
